민주당 전략 공천 향배에 촉각 이 기사를 공유합니다 페이스북(으)로 기사보내기 트위터(으)로 기사보내기 카카오톡(으)로 기사보내기 URL복사(으)로 기사보내기 닫기 var ___BANNER = "ban_1699606294"; 기자명 종합취재팀 입력 2026.04.17 07:29 수정 2026.04.17 07:32 페이스북(으)로 기사보내기 트위터(으)로 기사보내기 카카오톡(으)로 기사보내기 URL복사(으)로 기사보내기 바로가기 본문 글씨 키우기 본문 글씨 줄이기 ▲6ㆍ3 국회의원 재보궐선거.(출처=연합뉴스) 제9회 전국동시지방선거가 다가오는 가운데 전북 군산·김제·부안 갑·을 지역구가 재보궐선거의 핵심지로 떠오르고 있다. 동일 지역 내 두 선거구가 한꺼번에 선거를 치를 가능성이 커지면서 정치권의 이목이 집중되는 양상이다. 재선거가 확정된 군산·김제·부안갑은 더불어민주당 신영대 전 의원의 지역구였으나, 지난 1월 전직 사무장의 징역형 집행유예 선고로 신 전 의원이 의원직을 상실하며 공석이 됐다. 현재 민주당에서는 김의겸 전 새만금개발청장과 전수미 당 대변인, 문승우 전북도의회 의장 등이 유력 후보군으로 활동 중이다. 특히 정청래 민주당 대표가 ‘재보선 전략 공천’ 원칙을 공고히 함에 따라 당의 결정에 시선이 쏠리고 있다. 당 내부에서 제3의 인물을 검토 중이라는 추측이 나오는 가운데, 국민의힘에서는 오지성 전 당협위원장이 도전장을 내밀고 출격을 준비 중이다. ​인접 지역구인 군산·김제·부안을 역시 보궐선거 실시가 확실시되는 분위기다. 이원택 의원이 민주당 전북도지사 후보로 확정되면서 이달 중 의원직 사퇴가 예상되기 때문이다. 오는 30일까지 국회로부터 궐원 통보가 완료되면 이번 지방선거와 함께 보궐선거가 치러진다. 을 지역구 후보군으로는 강은호 전북대 교수, 김춘진 전 한국농수산식품유통공사 사장, 박지원 민주당 최고위원, 박준배 전 김제시장, 이광수 민주당 충북도당 사무처장, 김종회 전 국회의원 등이 거론되며 치열한 밑바닥 민심 잡기에 나서고 있다. 정치권 한 관계자는 “한 지역의 두 선거구에서 동시에 재보선이 열리는 것은 매우 이례적인 일”이라며 “민주당의 전략 공천 여파와 후보 확정 결과에 따라 전북 지역 선거 판세가 크게 요동칠 것으로 보인다”고 전망했다. 종합취재팀 goodtvnews@goodtv.co.kr 다른기사 보기 저작권자 © 데일리굿뉴스 무단전재 및 재배포 금지 SNS 기사보내기 $(document).ready(function(e) { $('.scrap-btn').on('click', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); var ___BANNER = "ban_1749001980"; 당신이 좋아할 만한 기사 #skin-53 > .item:not(:first-child) {margin-top:12px}
