연출했다. 전통과 첨단 기술이 결합된 이번 연출은 행사에 특별한 의미를 더하며 참석자들의 큰 관심을 모았다. 고창읍성에 도착한 성화는 고창군수를 거쳐 최초 주자에게 전달됐다. 성화 봉송의 첫 주자는 올해 결혼한 신혼부부로, 젊은 부부가 성화를 들고 힘차게 출발하는 장면은 사랑과 희망, 새로운 출발을 상징하며 현장에 특별한 감동을 더했다. 심덕섭 고창군수는 "방장산과 고창읍성은 역사와 전통이 살아 있는 장소로, 방장산에서 채화된 성화가 도민체육대회의 의미를 더욱 빛냈다"며 "방장산은 천혜의 자연경관과 생태적 가치를 지닌 지역의 대표 관광자원으로, 앞으로도 무궁무진한 발전 잠재력을 가지고 있다"고 밝혔다. 이어 "특히 신혼부부가 첫 주자로 나서면서 성화 봉송은 단순한 불꽃의 전달을 넘어 젊은 세대와 지역 공동체가 함께 미래를 열어가는 상징적인 출발이 됐다"고 말했다. 한편, 성화는 이날 봉송을 시작으로 고창 14개 읍면을 순회한 뒤, 9월12일 개회식에서 대회장에 도착해 성화 점화와 함께 제62회 전북특별자치도민체육대회의 막을 올리게 된다. 기사이력코드 취재(기획) 취재(기획) 취재(제보) 취재(자료보완) 보도자료 SNS 서핑 기타(국내외 논문·학술지) 기타(증권사 리포트) 기타(타 언론사 후속보도) 메트로신문 양수녕 기자 ysn6313@metroseoul.co.kr 다른기사 보기 Copyright ⓒ 메트로신문 & metroseoul.co.kr function goSearchPage(searchText){ location.href="/search?searchText="+encodeURI(searchText); return; } (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/35?type=COMPONENT", success: function (data) { $("#ZxBejhqxJS").after(data); $("#ZxBejhqxJS").remove(); } }); })() 메트로신문 지면 PDF 보기 // 현재 날짜 구하기 var now = new Date(); // 요일 체크 (0 = 일요일, 1 = 월요일, ..., 6 = 토요일) var dayName = now.getDay(); // 주말이면 금요일 날짜로 바꾸기 if (dayName === 0) { // 일요일이면 now.setDate(now.getDate() - 2); // 금요일로 이동 } else if (dayName === 6) { // 토요일이면 now.setDate(now.getDate() - 1); // 금요일로 이동 } // MMddDate: MMDD 형식 var MMddDate = ("0" + (now.getMonth() + 1)).slice(-2) + ("0" + now.getDate()).slice(-2); // yyyyMMddDate: yyyy/MM/dd 형식 var yyyyMMddDate = now.getFullYear() + "/" + ("0" + (now.getMonth() + 1)).slice(-2) + "/" + ("0" + now.getDate()).slice(-2); // yyyyMMddDate2: yyyy-MM-dd 형식 var yyyyMMddDate2 = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2); // 이미지 src URL 생성 var imageUrl = "https://pdf.metroseoul.co.kr/pdf/" + yyyyMMddDate + "/img/s10/kr_metro_1_" + MMddDate + "_01.jpg"; // HTML 요소에 값 삽입 document.getElementById('pdfImage').setAttribute('src', imageUrl); document.getElementById('pdfDate').textContent = yyyyMMddDate2; (function ()